CONTRACT_CHANGES = [('extension CameraOriginalQueue: OriginalFilesReading {}\nextension CameraOriginalStore: OriginalFilesReading {}\n/// Publication is optional for a queue run; platform grants and byte verification remain in its owner.\nprotocol OriginalFilesDestination: OriginalFilesReading {\n    func validateSelection() async throws\n    func publish(_ saved: SavedCameraFile, originalName: String?, folder: String?) async throws -> SavedCameraFile\n}\n\nextension ProviderOriginalStore: OriginalFilesDestination {}\n', 'extension CameraOriginalQueue: OriginalFilesReading {}\nextension CameraOriginalStore: OriginalFilesReading {}\nextension ProviderOriginalStore: OriginalFilesReading {}\n')]

def without_destination_contract(value):
    for new, old in CONTRACT_CHANGES:
        assert value.count(new) == 1, new
        value = value.replace(new, old, 1)
    return value

def previous_destination_source(path, value):
    normalizers = {
        'iosApp/ZTransfer/Network/CameraOriginalQueue.swift': without_destination_queue,
        'iosApp/ZTransfer/Storage/ProviderOriginalStore.swift': without_destination_provider,
        'iosApp/ZTransfer/Diagnostics/CameraHandshakeProbe.swift': without_destination_probe,
        'iosApp/ZTransfer/Storage/OriginalFilesReading.swift': without_destination_contract,
    }
    return normalizers.get(path, lambda text: text)(value)
